with candidate (n, title, artist, image_url, content) as (
    values
    (1, '民衆を導く自由の女神', 'ウジェーヌ・ドラクロワ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/La_Libert%C3%A9_guidant_le_peuple_-_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_RF_129_-_apr%C3%A8s_restauration_2024.jpg/960px-La_Libert%C3%A9_guidant_le_peuple_-_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_RF_129_-_apr%C3%A8s_restauration_2024.jpg', '1830年のフランス七月革命を主題に、ドラクロワが同年に描いた油彩画。翌1831年のサロンに出品され、フランス政府が買い上げた。現在はパリのルーヴル美術館が所蔵する。フリギア帽をかぶった女性が三色旗を掲げ、銃剣付きの銃を手に、倒れた人々を越えて民衆を導く。シルクハットの男性や二丁拳銃の少年など、さまざまな階層の人々が描き込まれ、寓意の女神と現実の市街戦が一つの画面で結びついている。'),
    (2, '風神雷神図屏風', '俵屋宗達', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Wind_God_and_Thunder_God_Screens_by_Tawaraya_Sotatsu_hi-res.png/960px-Wind_God_and_Thunder_God_Screens_by_Tawaraya_Sotatsu_hi-res.png', '江戸時代初期、寛永年間ごろの制作と考えられる二曲一双の屏風で、紙本金地着色。京都・建仁寺の所蔵で国宝に指定され、京都国立博物館に寄託されている。落款や印章はないが宗達の作とされる。金地の広い余白の両端に、風袋を担ぐ風神と太鼓を背負う雷神を配した大胆な構図が見どころ。のちに尾形光琳がこれを模写し、さらに酒井抱一が光琳の作をもとに描いた。')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, display_date)
select f.title, f.artist, f.image_url, f.content, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('ロンディノーネ、清水寺で日本初個展', 'スイス出身のウーゴ・ロンディノーネの日本初個展「静寂のかたち」が、10月27日から清水寺成就院で開かれる。', 'スイス出身のアーティスト、ウーゴ・ロンディノーネの日本初個展「静寂のかたち」が、京都・清水寺で2026年10月27日から11月12日まで開催される。中心となるのは、清水寺の塔頭で名勝「月の庭」で知られる成就院に設置される17体の石の人物彫刻で、庭園の石や苔、借景の山々と呼応する。床の間には赤と黒で描かれた太陽の絵画も展示される。ロンディノーネは1964年スイス・ブルンネン生まれで、97年からニューヨークを拠点に活動している。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33205')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('東博、モロッコ王国国立図書館と協定', '東京国立博物館が10月19日、モロッコ王国国立図書館と学術研究や人材交流での連携を目的とする協定を結んだ。', '東京国立博物館とモロッコ王国国立図書館が2026年10月19日、学術研究や人材交流など幅広い分野での連携強化を目的とする国際交流協定（MOU）を締結した。東博の平成館で行われた締結式には、藤原誠館長とモロッコ王国国立図書館のサミラ・エル・マリジ館長が出席し、協定書に署名した。2026年は日本とモロッコの外交関係樹立70周年にあたり、東博は同年6月にもモロッコ国立博物館財団とMOUを締結している。', '', '美術館', 'https://bijutsutecho.com/magazine/news/report/33216')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('京都初の大規模アートブックフェア開催へ', '「KYOTO ART BOOK FAIR」が2027年5月21日から23日まで京都市京セラ美術館で初開催される。', '京都初となる大規模アートブックフェア「KYOTO ART BOOK FAIR」が、2027年5月21日から23日の3日間、京都市京セラ美術館で初開催されることが発表された。主催は、京都の株式会社長谷ビルと、2009年から東京で「TOKYO ART BOOK FAIR」を開いてきた東京アートブックフェア事務局が共同で立ち上げた京都アートブックフェア実行委員会。会場は本館の北回廊と南回廊で、国内外から約200組の出展を予定している。出展者の募集は2026年10月24日から11月20日まで。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33229')
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url)
values ('ディーター・ラムスの公式巡回展が日本初開催', 'ドイツのデザイナー、ディーター・ラムスの公式巡回展が11月17日から多摩美術大学上野毛キャンパスで開かれる。', 'ドイツを代表するインダストリアルデザイナー、ディーター・ラムスの公式巡回展「ディーター・ラムスが教えてくれたこと『より少なく、しかしより良く』」が、多摩美術大学上野毛キャンパスのギャラリー「Sala Blu」で2026年11月17日から12月16日まで開催される。ディーター＆インゲボルグ・ラムス財団が企画・監修する公式巡回展で、日本では初開催。同ギャラリーの開館記念展となる。ラムスは1955年にブラウン社に入社し、レコードプレーヤー「SK 4」などで知られ、「良いデザインの10原則」を提唱した。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33191')
on conflict (source_url) do nothing;
